steps.eval:
(()=>{const g=__game; g.showScreen(null); g.mode='play'; g.player.release(); const rep={}; let runs=0, hits=0;
 const cps=g.course.checkpoints;
 for (let ci=0; ci<cps.length; ci++) for (let k=0;k<24;k++) { const cp=cps[ci]; g.time=0; g.mode='play'; g.course.time=k*0.53+ci*0.31; g.player.respawn(cp); runs++; let wasHit=false;
   const jumpAt=(k%3===0)?1e9:0.3+(k%7)*0.17;
   g.simulate(3.5,(t,p)=>{ if(p.state==='hit') wasHit=true;
     const pl=g.course.platforms.find(d=>p.pos.x>=d.x0-0.25&&p.pos.x<=d.x1+0.25);
     if(pl && Math.abs(p.pos.z)<1.2+0.28 && p.state!=='water'){ const top=pl.topAt(Math.min(Math.max(p.pos.x,pl.x0),pl.x1)); if(p.pos.y<top-0.08 && p.pos.y+1.76>top-pl.thick){ const key='body inside deck, state '+p.state; rep[key]=(rep[key]||0)+1; } }
     return {move:1, jump:t>jumpAt&&t<jumpAt+0.35}; });
   if(wasHit) hits++; }
 return {runs, hits, deck_penetration_frames:rep}})()
